mapper.select:
WITH future_nodes AS ( SELECT event.id AS publicMatterId, event.title AS name, node.id AS timeNodeId, node.label AS nodeName, node.start_time AS reminderAt FROM public_event event INNER JOIN timeline node ON node.target_type = 3 AND node.target_id = event.id AND node.start_time > #{evaluatedAt} AND node.start_precision = 2 AND node.end_time IS NULL AND node.end_precision = 0 WHERE event.publish_status = 1 AND event.lifecycle_status = 0 AND event.cancelled_at IS NULL AND event.deleted_at IS NULL ), ranked_nodes AS ( SELECT node.publicMatterId, node.name, node.timeNodeId, node.nodeName, node.reminderAt, ROW_NUMBER() OVER ( PARTITION BY node.publicMatterId ORDER BY node.reminderAt ASC, COALESCE(node.timeNodeId, 0) ASC ) AS nodeRank FROM future_nodes node ), eligible_nodes AS ( SELECT node.publicMatterId, node.name, node.timeNodeId, node.nodeName, node.reminderAt FROM ranked_nodes node WHERE node.nodeRank = 1 ), subscribed_nodes AS ( SELECT node.publicMatterId, node.name, node.timeNodeId, node.nodeName, node.reminderAt FROM eligible_nodes node WHERE EXISTS ( SELECT 1 FROM exam_subscription subscription WHERE subscription.exam_info_id = node.publicMatterId AND subscription.user_id = #{userId} AND subscription.status = 1 AND subscription.notify_enable = 1 ) ), chosen_nodes AS ( SELECT subscribed.publicMatterId, subscribed.name, subscribed.timeNodeId, subscribed.nodeName, subscribed.reminderAt, 'SUBSCRIPTIONS' AS source FROM subscribed_nodes subscribed
UNION ALL
SELECT node.publicMatterId, node.name, node.timeNodeId, node.nodeName, node.reminderAt, 'DEFAULT' AS source FROM eligible_nodes node WHERE NOT EXISTS (SELECT 1 FROM subscribed_nodes) ) SELECT candidate.publicMatterId, candidate.name, candidate.timeNodeId, candidate.nodeName, candidate.reminderAt, candidate.source FROM chosen_nodes candidate ORDER BY candidate.reminderAt ASC, candidate.publicMatterId ASC, COALESCE(candidate.timeNodeId, 0) ASC LIMIT #{limit}

SELECT id, contract_version, lifecycle_status, source_name, source_url, title, summary, event_type, edition_label, cover_attachment_id, publish_status, official_url, comment_count, like_count, view_count, published_at FROM public_event WHERE publish_status = 1 AND deleted_at IS NULL AND event_type = #{eventType} AND lifecycle_status = #{lifecycleStatus}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%'))
AND (published_at < (SELECT published_at FROM public_event WHERE id = #{lastId}) OR (published_at = (SELECT published_at FROM public_event WHERE id = #{lastId}) AND id < #{lastId}))
ORDER BY published_at DESC, id DESC LIMIT #{limit}

SELECT COALESCE(view_count, 0)
FROM public_event
WHERE id = #{id}

mapper.update:
UPDATE public_event
SET view_count = COALESCE(view_count, 0) + #{delta}
WHERE id = #{id}

mapper.select:
SELECT id, title, publish_status, lifecycle_status, updated_at
FROM public_event WHERE deleted_at IS NULL

    AND title LIKE CONCAT('%', #{query.keyword}, '%')

AND publish_status = #{query.publishStatus}
AND lifecycle_status = #{query.lifecycleStatus}
ORDER BY updated_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM public_event WHERE deleted_at IS NULL

    AND title LIKE CONCAT('%', #{query.keyword}, '%')

AND publish_status = #{query.publishStatus}
AND lifecycle_status = #{query.lifecycleStatus}
